const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const brand = typeof $json.brand === 'string' ? $json.brand.trim().toLowerCase() : '';
const updatesJson = typeof $json.updatesJson === 'string' ? $json.updatesJson : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const brandPattern = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const statuses = ['imported', 'needs_review', 'enriched', 'emailed', 'opened', 'followed_up', 'replied', 'closed'];
const allowedFields = ['linkedinCompanyUrl', 'contactName', 'contactEmail', 'linkedinUrl', 'website', 'region', 'tier', 'status', 'notes'];
let error = null;
let updates = [];

if (!uuidPattern.test(sessionId)) {
  error = { code: 'INVALID_SESSION', message: 'The update proposal needs a valid conversation session.' };
} else if (brand === '' || brand.length > 40 || !brandPattern.test(brand)) {
  error = { code: 'INVALID_BRAND', message: 'Say which brand these prospects belong to, such as oddtoe or datalabs.' };
} else if (updatesJson.trim() === '' || updatesJson.length > 100000) {
  error = { code: 'INVALID_UPDATES', message: 'Pass the updates as a JSON array of {company, fields} objects.' };
} else {
  let parsed;
  try { parsed = JSON.parse(updatesJson); } catch {
    error = { code: 'INVALID_UPDATES', message: 'The updates are not valid JSON. Pass a JSON array of {company, fields} objects.' };
  }
  if (!error && (!Array.isArray(parsed) || parsed.length === 0 || parsed.length > 100)) {
    error = { code: 'INVALID_UPDATES', message: 'Pass between 1 and 100 updates in one proposal.' };
  }
  if (!error) {
    for (const candidate of parsed) {
      if (error) break;
      if (typeof candidate !== 'object' || candidate === null || Array.isArray(candidate)) {
        error = { code: 'INVALID_UPDATES', message: 'Every update needs a company and a fields object.' };
        break;
      }
      const company = typeof candidate.company === 'string' ? candidate.company.trim() : '';
      const rawFields = candidate.fields;
      if (company === '' || company.length > 120 || typeof rawFields !== 'object' || rawFields === null) {
        error = { code: 'INVALID_UPDATES', message: 'Every update needs a company name and a fields object.' };
        break;
      }
      const fields = {};
      for (const [key, value] of Object.entries(rawFields)) {
        if (!allowedFields.includes(key)) {
          error = { code: 'INVALID_FIELD', message: `Field "${key}" cannot be updated. Allowed: ${allowedFields.join(', ')}.` };
          break;
        }
        if (typeof value !== 'string' || value.length > (key === 'notes' ? 1000 : 300)) {
          error = { code: 'INVALID_FIELD', message: `Field "${key}" must be a short text value.` };
          break;
        }
        fields[key] = value.trim();
      }
      if (error) break;
      if (fields.status !== undefined && !statuses.includes(fields.status)) {
        error = { code: 'INVALID_STATUS', message: `Status must be one of: ${statuses.join(', ')}.` };
        break;
      }
      if (fields.linkedinCompanyUrl !== undefined && fields.linkedinCompanyUrl !== '' && !/^https:\/\/(www\.)?linkedin\.com\/company\//i.test(fields.linkedinCompanyUrl)) {
        error = { code: 'INVALID_URL', message: 'LinkedIn company URLs must start with https://www.linkedin.com/company/' };
        break;
      }
      if (Object.keys(fields).length === 0) {
        error = { code: 'INVALID_UPDATES', message: `The update for ${company} changes nothing.` };
        break;
      }
      const entry = { company, fields };
      if (typeof candidate.listName === 'string' && candidate.listName.trim() !== '') {
        entry.listName = candidate.listName.trim().slice(0, 120);
      }
      updates.push(entry);
    }
  }
}

const proposedInput = error ? {} : { brand, updates };
const auditInput = { brand, updateCount: updates.length };
const actionId = error ? '' : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => { const random = Math.floor(Math.random() * 16); const value = character === 'x' ? random : (random & 0x3) | 0x8; return value.toString(16); });
const confirmationText = error ? '' : `CONFIRM ${actionId.replaceAll('-', '').slice(-8).toUpperCase()}`;
const expiresAt = error ? '' : new Date(Date.now() + 5 * 60 * 1000).toISOString();
return {
  json: {
    valid: error === null,
    sessionId,
    actionId,
    actionType: 'update_prospects',
    brand,
    updateCount: updates.length,
    preview: updates.slice(0, 5).map((entry) => `${entry.company}: ${Object.keys(entry.fields).join(', ')}`),
    proposedInput,
    auditInput,
    confirmationText,
    expiresAt,
    ...(error ? { response: { ok: false, error } } : {})
  }
};

const proposal = $('Validate Update Proposal').first().json;
if (!Number.isInteger($json.id)) {
  return {
    json: {
      ...proposal,
      response: {
        ok: false,
        error: {
          code: 'CONFIRMATION_DATA_UNAVAILABLE',
          message: 'The update proposal could not be saved. Rerun local setup, then try again.'
        }
      }
    }
  };
}
return {
  json: {
    ...proposal,
    response: {
      ok: true,
      confirmationRequired: true,
      action: {
        type: 'update_prospects',
        brand: proposal.brand,
        updateCount: proposal.updateCount,
        preview: proposal.preview
      },
      confirmation: {
        phrase: proposal.confirmationText,
        expiresAt: proposal.expiresAt
      },
      message: `No prospects changed. ${proposal.updateCount} update(s) are ready for ${proposal.brand}. Ask the user to reply with exactly "${proposal.confirmationText}" within five minutes.`
    }
  }
};

const response = $json.response;
const error = response?.ok === false ? String(response.error?.message ?? 'Tool failed') : '';
return {
  json: {
    occurredAt: new Date().toISOString(),
    sessionId: String($json.sessionId ?? ''),
    requestId: String(''),
    toolName: 'propose_update_prospects',
    proposedInput: JSON.stringify($json.auditInput ?? $json.proposedInput ?? {}),
    result: JSON.stringify(response),
    error,
    response
  }
};

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
